#!/usr/bin/env python3
import sys
import itertools


def solve(N: int, M: int, P: "List[int]", Y: "List[int]"):

    L = []
    R = [""] * M
    for p,y,i in zip(P,Y,range(M)):
        L.append((i,p,y))
    L.sort(key=lambda x: x[1]*10**10+x[2])

    for k,g in itertools.groupby(L,key=lambda x: x[1]):
        for i,gg in enumerate(g):
            R[gg[0]] = str(gg[1]).zfill(6) + str(i+1).zfill(6)

    for r in R:
        print(r)




# Generated by 1.1.4 https://github.com/kyuridenamida/atcoder-tools  (tips: You use the default template now. You can remove this line by using your custom template)
def main():
    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    N = int(next(tokens))  # type: int
    M = int(next(tokens))  # type: int
    P = [int()] * (M)  # type: "List[int]" 
    Y = [int()] * (M)  # type: "List[int]" 
    for i in range(M):
        P[i] = int(next(tokens))
        Y[i] = int(next(tokens))
    solve(N, M, P, Y)

if __name__ == '__main__':
    main()
